<div class="row g-3"><div class="col-xl-5"><div class="card"><div class="card-header border-bottom border-dashed"><h4 class="header-title mb-0">Cari Siswa</h4></div><div class="card-body"><div class="row g-2 align-items-end"><div class="col-md-10"><input id="q" class="form-control" placeholder="Nama/NIS/NISN"></div><div class="col-md-2 d-grid"><button class="btn btn-primary" onclick="cariSiswa()"><i class="ri-search-line me-1"></i>Cari</button></div></div><div id="hasil_siswa" class="mt-3"></div></div></div><div class="card"><div class="card-header border-bottom border-dashed"><h4 class="header-title mb-0">Riwayat Keringanan</h4></div><div class="card-body" id="riwayat"><div class="empty-state">Pilih siswa.</div></div></div></div><div class="col-xl-7"><div class="card"><div class="card-header border-bottom border-dashed"><h4 class="header-title mb-0">Potongan atau Pembebasan</h4></div><div class="card-body"><form id="form"><input type="hidden" id="id_siswa"><div class="alert alert-info" id="identitas">Pilih siswa terlebih dahulu.</div><div class="mb-3"><label class="form-label">Pilih Tagihan</label><select name="id_tagihan_siswa" id="tagihan" class="form-select"><option value="">Pilih tagihan</option></select></div><div class="row g-3"><div class="col-md-6"><label class="form-label">Nominal Awal</label><input id="nominal_awal" class="form-control" disabled></div><div class="col-md-6"><label class="form-label">Sudah Dibayar</label><input id="sudah_dibayar" class="form-control" disabled></div><div class="col-md-6"><label class="form-label">Jenis Keringanan</label><select name="jenis_keringanan" id="jenis" class="form-select"><option>Potongan Nominal</option><option>Potongan Persen</option><option>Pembebasan Penuh</option></select></div><div class="col-md-6"><label class="form-label">Nilai Keringanan</label><input name="nilai_keringanan" id="nilai" type="text" inputmode="numeric" autocomplete="off" class="form-control money-input"></div><div class="col-md-6"><label class="form-label">Nominal Akhir</label><input id="nominal_akhir" class="form-control" disabled></div><div class="col-md-6"><label class="form-label">Sisa Setelah Aturan</label><input id="sisa" class="form-control" disabled></div><div class="col-12"><label class="form-label">Alasan</label><textarea name="alasan" class="form-control" required></textarea></div><div class="col-12"><button type="button" id="btn_simpan" class="btn btn-primary">Simpan Keringanan</button></div></div></form></div></div></div></div>
<script>
var tagihanMap={};$(function(){$('#q').keyup(function(e){if(e.key==='Enter')cariSiswa();});$('#tagihan,#jenis,#nilai').on('change input',previewHitung);$('#jenis').change(aturInputKeringanan);aturInputKeringanan();$('#btn_simpan').click(saveData);});
function cariSiswa(){$.post('<?= base_url('keringanan/cari_siswa') ?>',{q:$('#q').val()},function(rows){var h='';if(!rows.length)h='<div class="empty-state">Siswa tidak ditemukan.</div>';rows.forEach(function(r){h+='<button class="list-group-item list-group-item-action border rounded mb-2" onclick=\'pilihSiswa('+JSON.stringify(r)+')\'><strong>'+escapeHtml(r.nama_siswa)+'</strong><br><small>'+escapeHtml(r.nis)+' | '+escapeHtml(r.nama_kelas)+'</small></button>';});$('#hasil_siswa').html(h);},'json').fail(ajaxError);}
function pilihSiswa(r){$('#id_siswa').val(r.id_siswa);$('#identitas').html('<strong>'+escapeHtml(r.nama_siswa)+'</strong><br>'+escapeHtml(r.nis)+' / '+escapeHtml(r.nisn)+' | '+escapeHtml(r.nama_kelas));loadTagihan();loadRiwayat();}
function loadTagihan(){$.post('<?= base_url('keringanan/tagihan_siswa') ?>',{id_siswa:$('#id_siswa').val()},function(rows){tagihanMap={};var h='<option value="">Pilih tagihan</option>';rows.forEach(function(r){tagihanMap[r.id]=r;h+='<option value="'+r.id+'">'+escapeHtml(r.nama_tagihan)+' - '+escapeHtml(r.nama_bulan)+' '+r.tahun+' | Sisa '+formatRupiah(r.sisa_tagihan)+'</option>';});$('#tagihan').html(h);},'json').fail(ajaxError);}
function aturInputKeringanan(){var jenis=$('#jenis').val(),input=$('#nilai'),sebelumnya=input.data('jenis');if(sebelumnya&&sebelumnya!==jenis)input.val('');input.data('jenis',jenis);if(jenis==='Pembebasan Penuh'){input.prop('disabled',true).removeClass('money-input').val('0');}else if(jenis==='Potongan Persen'){input.prop('disabled',false).removeClass('money-input').attr('inputmode','decimal').attr('placeholder','0 - 100');}else{input.prop('disabled',false).addClass('money-input').attr('inputmode','numeric').attr('placeholder','Nominal potongan');if(input.val()!=='')input.val(formatMoneyInput(input.val()));}previewHitung();}
function previewHitung(){var r=tagihanMap[$('#tagihan').val()];if(!r)return;var awal=Number(r.nominal_awal),dibayar=Number(r.nominal_dibayar),jenis=$('#jenis').val(),nilai=jenis==='Potongan Nominal'?parseMoneyInput($('#nilai').val()):Number($('#nilai').val()||0),pot=jenis==='Potongan Nominal'?nilai:jenis==='Potongan Persen'?awal*Math.min(100,nilai)/100:awal,akhir=Math.max(0,awal-pot),sisa=Math.max(0,akhir-dibayar);$('#nominal_awal').val(formatRupiah(awal));$('#sudah_dibayar').val(formatRupiah(dibayar));$('#nominal_akhir').val(formatRupiah(akhir));$('#sisa').val(formatRupiah(sisa));}
function saveData(){confirmAction('Simpan keringanan?','Perubahan akan memengaruhi nominal dan sisa tagihan siswa.',function(){$.post('<?= base_url('keringanan/simpan') ?>',serializeMoneyForm('#form'),function(r){Swal.fire(r.result==='true'?'Berhasil':'Gagal',r.message,r.result==='true'?'success':'error');if(r.result==='true'){loadTagihan();loadRiwayat();$('#form [name=alasan]').val('');}},'json').fail(ajaxError);});}
function loadRiwayat(){$.post('<?= base_url('keringanan/riwayat') ?>',{id_siswa:$('#id_siswa').val()},function(rows){var h='';if(!rows.length)h='<div class="empty-state">Belum ada keringanan.</div>';rows.forEach(function(r){h+='<div class="border-bottom py-3"><div class="d-flex justify-content-between"><strong>'+escapeHtml(r.jenis_keringanan)+'</strong><span class="badge bg-'+(r.status==='Aktif'?'success':'secondary')+'">'+escapeHtml(r.status)+'</span></div><div>'+formatRupiah(r.nominal_awal)+' → '+formatRupiah(r.nominal_setelah_keringanan)+'</div><small class="text-muted">'+escapeHtml(r.alasan)+' | '+escapeHtml(r.tanggal)+'</small>'+(r.status==='Aktif'?'<div class="mt-2"><button class="btn btn-sm btn-outline-danger" onclick="batalkan('+r.id+')">Batalkan</button></div>':'')+'</div>';});$('#riwayat').html(h);},'json');}
function batalkan(id){Swal.fire({title:'Batalkan keringanan',input:'textarea',inputLabel:'Alasan pembatalan',showCancelButton:true,preConfirm:function(v){if(!v)Swal.showValidationMessage('Alasan wajib diisi');return v;}}).then(function(x){if(x.isConfirmed)$.post('<?= base_url('keringanan/batalkan') ?>',{id:id,alasan:x.value},function(r){Swal.fire(r.result==='true'?'Berhasil':'Gagal',r.message,r.result==='true'?'success':'error');loadTagihan();loadRiwayat();},'json').fail(ajaxError);});}
</script>
